<script setup lang="ts">import {fixed,probability,logValue} from '../utils/format';defineProps<{candidate:any}>()</script><template><section class="branch-panel"><p class="eyebrow">EXPECTED ENTROPY / RAW BRANCH RECORD</p><h2>{{candidate.node_id}} · 候选分支明细</h2><div class="table-wrap"><table><thead><tr><th>状态</th><th>P(X|E)</th><th>log P(X|E)</th><th>H(Q|E,X) bit</th><th>P(Q=1|E,X)</th><th>联合logZ</th></tr></thead><tbody><tr v-for="b in candidate.branches" :key="b.state"><td>{{b.state}}</td><td>{{probability(b.probability,b.probability_underflow)}}</td><td>{{logValue(b.log_probability)}}</td><td>{{b.conditional_entropy===null?'严格零分支跳过':fixed(b.conditional_entropy,6)}}</td><td>{{b.inference?probability(b.inference.posterior[1].probability,b.inference.posterior[1].probability_underflow):'—'}}</td><td>{{b.inference?logValue(b.inference.log_evidence):'−∞'}}</td></tr></tbody></table></div><p class="method-note">H当前={{fixed(candidate.prior_entropy,8)}}；期望={{fixed(candidate.expected_entropy,8)}}；原始IG={{fixed(candidate.raw_information_gain,10)}} bit。微负容差{{candidate.negative_tolerance}}，截断标记{{candidate.micro_negative_clipped}}。分支权重的log分母为{{logValue(candidate.marginal.log_evidence)}}。</p></section></template>
